"""Sourced model answer pages. Static markup and visible structured data."""
import html,json
E=lambda s:html.escape(str(s),quote=True)
CSS='''.mr{margin:30px 0}.mr h2{font-size:clamp(26px,3.7vw,38px);line-height:1.2;letter-spacing:-.025em;margin:35px 0 20px}.mr h3{font-size:20px;line-height:1.35;margin:0 0 14px}.mr p,.mr li{font-size:15px;line-height:1.85;color:var(--p-muted)}.mr-answer{padding:30px;border:1px solid var(--p-line);border-left:4px solid var(--p-ac);border-radius:12px;background:var(--p-soft)}.mr-answer p{font-size:18px;color:var(--p-fg)}.mr-kicker{font-size:11px;letter-spacing:.1em;text-transform:uppercase;font-weight:700;color:var(--p-ac)}.mr-nav{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.mr-nav a{font-size:13px;padding:10px 14px;border:1px solid var(--p-line);border-radius:7px;text-decoration:none}.mr-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.mr-card{border:1px solid var(--p-line);border-radius:12px;padding:26px;min-width:0}.mr a{color:var(--p-ac);overflow-wrap:anywhere}.mr-stat{display:block;font-size:32px;font-weight:700;line-height:1.2;margin:12px 0}.mr-unit{font-size:12px;color:var(--p-muted)}.mr-visual svg{width:100%;height:auto;display:block}.mr-visual{padding:24px;background:var(--p-soft);border-radius:12px}.mr-visual p{font-size:12px}.mr-faq details{border:1px solid var(--p-line);border-radius:10px;margin:12px 0;padding:0 20px}.mr-faq summary{font-size:17px;font-weight:700;cursor:pointer;padding:18px 0}.mr-faq p{margin:0 0 20px}.mr-note{font-size:12px!important}.mr-checklist{padding-left:22px}.mr-related{display:flex;flex-wrap:wrap;gap:15px}.mr-related a{padding:14px;border:1px solid var(--p-line);border-radius:8px;font-size:14px}@media(max-width:650px){.mr-grid{grid-template-columns:minmax(0,1fr)}.mr-card,.mr-answer{padding:22px}.mr-nav a{flex:1 1 calc(50% - 12px);text-align:center;min-width:0;box-sizing:border-box}.mr-visual{padding:15px}.mr-visual svg{display:none}.mr-visual .mr-textchart{display:block}}.mr-textchart{display:none}'''
def render(m,d,technical):
 p=m['rich_model'];name=p['name'];source='<a href="'+E(p['url'])+'">Offizielle Dokumentation: '+E(name)+'</a>';base='https://kifachblatt.de' if technical else 'https://intelligenz-welt.de';path='/ki-modelle/'+m['slug']+('' if technical else '/')
 out='<section class="mr"><div class="mr-answer"><div class="mr-kicker">'+('Technisches Modellportrait' if technical else 'Das Modell einfach erklärt')+'</div><h2>'+E(p['headline'])+'</h2><p>'+E(p['answer'])+'</p>'+source+'<p class="mr-note">Quellen geprüft: 19.10.2026. Herstellerangaben, kein eigener Modelltest.</p></div><nav class="mr-nav" aria-label="Auf dieser Modellseite">'+''.join('<a href="#'+i+'">'+t+'</a>' for i,t in [('einsatz','Einsatz & Grenzen'),('daten','Kontext & Ausgabe'),('preise','API-Preise'),('faq','Fragen & Antworten')])+'</nav><h2 id="einsatz">Wofür eignet sich '+E(name)+'?</h2><p>'+E(p['technical'] if technical else p['practical'])+'</p><div class="mr-grid">'
 for title,text in p['sections']:out+='<article class="mr-card"><h3>'+E(title)+'</h3><p>'+E(text)+'</p>'+source+'</article>'
 out+='</div><h2 id="daten">Kontextfenster ist nicht Ausgabelimit.</h2><div class="mr-grid">'
 for value,label in [(f"{p['context']:,}".replace(',','.'),'Token Kontextfenster'),(f"{p['maxout']:,}".replace(',','.'),'maximale Ausgabe-Token, synchron')]:out+='<div class="mr-card"><span class="mr-stat">'+value+'</span><span class="mr-unit">'+label+'</span></div>'
 out+='</div><div class="mr-visual"><svg viewBox="0 0 650 180" role="img" aria-label="'+E(name)+' hat '+str(p['context'])+' Token Kontext und '+str(p['maxout'])+' maximale Ausgabe-Token. Gemeinsame Skala, nicht addieren."><title>Kontext und maximale Ausgabe, in Token</title><text x="0" y="22" font-size="17">Kontext</text><rect x="0" y="35" width="550" height="20" rx="4" fill="#7040cd"/><text x="0" y="90" font-size="17">Maximale Ausgabe (synchron)</text><rect x="0" y="105" width="'+str(p['maxout']/p['context']*550)+'" height="20" rx="4" fill="#ac97ce"/><text x="0" y="165" font-size="14">0</text><text x="550" y="165" text-anchor="end" font-size="14">'+str(p['context'])+' Token</text></svg><div class="mr-textchart"><b>Kontext: '+str(p['context'])+' Token</b><p>Maximale Ausgabe synchron: '+str(p['maxout'])+' Token</p></div><p>Zwei unterschiedliche Grenzen auf gemeinsamer Nullskala, nicht addieren. '+source+'</p></div><h2 id="preise">Was kostet '+E(name)+' über die API?</h2><div class="mr-grid">'
 for price,label in [(p['input'],'Standard-Eingabe'),(p['output'],'Standard-Ausgabe')]:out+='<div class="mr-card"><h3>'+label+'</h3><span class="mr-stat">'+str(price)+' USD</span><span class="mr-unit">je 1 Mio. Texttoken · Basisrate</span></div>'
 out+='</div><p>'+E(p['pricing_note'])+'</p><p class="mr-note">Preisstand 19.10.2026. '+source+'</p><h2>'+('Technische Prüfliste vor der Migration' if technical else 'Vor dem Einsatz prüfen')+'</h2><ul class="mr-checklist">'+''.join('<li>'+E(t)+'</li>' for t in p['migration'])+'</ul><h2 id="faq">Häufige Fragen zu '+E(name)+'</h2><div class="mr-faq">'
 for q,a in p['faq']:out+='<details><summary>'+E(q)+'</summary><p>'+E(a)+'</p></details>'
 out+='</div><p class="mr-note">Alle Antworten beziehen sich auf die verlinkte Herstellerdokumentation und den angegebenen Stand. Kein unabhängiger Benchmark, keine Garantie für Verfügbarkeit oder Ergebnisqualität.</p><h2>Weiterlesen und vergleichen</h2><div class="mr-related">'
 for x in d['models']:
  if x.get('rich_model') and x['slug']!=m['slug']:out+='<a href="/ki-modelle/'+x['slug']+('' if technical else '/')+'">'+E(x['name'])+' im Portrait ↗</a>'
 out+='</div></section>'
 faq={'@context':'https://schema.org','@type':'FAQPage','@id':base+path+'#faq','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faq']]}
 crumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Start','item':base+'/'},{'@type':'ListItem','position':2,'name':'KI-Modelle','item':base+'/ki-modelle'+('' if technical else '/')},{'@type':'ListItem','position':3,'name':name,'item':base+path}]}
 return out+'<script type="application/ld+json">'+json.dumps([faq,crumb],ensure_ascii=False).replace('</','<\/')+'</script>'
